import * as S from "node:stream";
function main(): void {
  console.log(S.addAbortSignal.length, S.isReadable.length, S.isErrored.length, S.getDefaultHighWaterMark.length, S.setDefaultHighWaterMark.length, S.destroy.length, S.duplexPair.length);
  const d: any = new S.Duplex();
  console.log(typeof d.setDefaultEncoding, Array.isArray(d.writableBuffer), d.setDefaultEncoding("utf8") === d);
  const t: any = new S.PassThrough();
  console.log(typeof t.setDefaultEncoding, typeof t.writableBuffer);
  console.log(typeof S.Stream, typeof S.Stream.Readable, typeof S.Stream.Writable, typeof S.Stream.pipeline);
  const inst: any = new S.Stream();
  console.log(typeof inst.pipe, typeof inst.on, typeof inst.emit, typeof inst.domain);
}
